    desc: "Política pública federal (execução municipal pela SMAAI, em parceria com a Conab e o MDS) que compra alimentos diretamente de agricultores familiares e distribui a instituições que atendem pessoas em situação de vulnerabilidade e insegurança alimentar. Em Boa Vista, atende cerca de 4 mil famílias por meio de entidades indicadas pelo <strong>Conselho Municipal de Assistência Social</strong>, vinculado à Secretaria Municipal de Gestão Social (Semges).<br><u>Quem pode fornecer:</u> agricultores familiares, assentados da reforma agrária, indígenas, extrativistas, quilombolas e pescadores artesanais, organizados em cooperativas/associações ou de forma individual (DAP/CAF).<br><u>Quem recebe:</u> instituições socioassistenciais (abrigos, entidades de acolhimento, associações comunitárias) previamente cadastradas junto ao município - não é atendimento direto de balcão ao cidadão.<br><u>Papel do CRAS:</u> orientar entidades da rede sobre o cadastro junto à Semges/Conselho Municipal de Assistência Social e, quando pertinente, articular o encaminhamento de famílias a instituições beneficiárias do programa.<br>Fonte: Prefeitura de Boa Vista (SMAAI) e Conab, 2023-2026.",
