    desc: "Organização não governamental sem fins lucrativos, referência nacional em inclusão social e empregabilidade jovem, com unidade em Boa Vista. Faz a intermediação entre estudantes e empresas para vagas de estágio (ensino médio, técnico e superior) e para o Programa de Aprendizagem, em áreas como Administração, Educação, Direito, Contabilidade, Construção Civil, Marketing, Farmácia, Comunicação, Saúde, Design e Secretariado, entre outras. O cadastro é gratuito e feito pelo Portal CIEE (portal.ciee.org.br), onde o candidato monta o currículo e pode incluir redação e vídeo de apresentação para ampliar as chances de convocação; o atendimento presencial em Boa Vista serve para tirar dúvidas sobre cadastro e vagas. Atua em parceria com o SINE/RR e a Setrabes, inclusive no Projeto Jovem Aprendiz."
