    desc: "⚖️ <strong>Base legal:</strong> arts. 96 e 125 da Constituição Federal (autonomia administrativa e financeira do Judiciário e organização da Justiça estadual), Constituição do Estado de Roraima e Lei nº 6.015/1973 (Lei de Registros Públicos, que rege os cartórios e o registro civil). Órgão máximo do Poder Judiciário estadual, responsável pela 2ª instância e pela administração das Varas de 1ª instância nas comarcas do Estado.<br><u>Quem pode ser atendido:</u> qualquer cidadão com processo em trâmite ou que precise de serviços de cartório/registro civil; a Vara da Justiça Itinerante (VIJ) atende gratuitamente comunidades indígenas e municípios de difícil acesso, sem necessidade de deslocamento até a capital.<br><u>Documentos:</u> variam conforme o serviço - RG e CPF para consultas processuais e emissão de certidões; para os mutirões da Justiça Itinerante, costuma-se exigir documentos pessoais básicos e, quando aplicável, certidão de nascimento dos filhos (casamento coletivo).<br>📝 <u>Como funciona:</u> acompanhamento processual pelo Balcão Virtual e pelo Processo Judicial Eletrônico (PJe); a Vara Itinerante divulga cronograma de visitas a municípios e comunidades para mutirões de emissão de documentos, casamentos coletivos e audiências.<br><u>Áreas de atuação:</u> Varas Cíveis, Criminais, de Família e da Infância e Juventude nas comarcas, Corregedoria-Geral de Justiça (fiscalização de cartórios e unidades judiciais) e serviços de registro civil."
