    desc: "⚖️ <strong>Base legal:</strong> art. 121 da Constituição Federal (organização e competência da Justiça Eleitoral), Código Eleitoral (Lei nº 4.737/1965) e resoluções do TSE. Responsável pela organização e fiscalização das eleições em Roraima e pelos serviços ao eleitor.<br><u>Quem pode ser atendido:</u> qualquer cidadão brasileiro maior de 16 anos que precise tirar o título de eleitor pela primeira vez (alistamento), transferir domicílio eleitoral, justificar ausência às urnas, regularizar título cancelado/suspenso ou emitir certidão de quitação eleitoral.<br><u>Documentos:</u> documento oficial com foto (RG, CNH ou passaporte), CPF e comprovante de residência atualizado; para justificativa eleitoral fora do prazo ou 2ª via de título, consultar exigências específicas no cartório da Zona Eleitoral.<br>📝 <u>Como funciona:</u> a maioria dos serviços é feita pelo aplicativo/site e-Título ou pelo autoatendimento eleitoral (título net); atendimento presencial é feito na Zona Eleitoral correspondente ao bairro/domicílio, mediante agendamento quando exigido; o TRE-RR também realiza ações itinerantes em municípios e comunidades do interior.<br><u>Áreas de atuação:</u> alistamento e regularização eleitoral, fiscalização de eleições e partidos, Disque-Eleitor para dúvidas gerais e Zonas Eleitorais distribuídas por bairros de Boa Vista e municípios do interior."
