    cat: ["juridico"],
    address: "Justiça do Trabalho: Av. Benjamin Constant, 1863 - Centro, Boa Vista-RR, CEP 69301-072<br>MPT/RR: Rua Capitão Franco de Carvalho, 352 - São Francisco, Boa Vista-RR, CEP 69305-120",
