    services: "Inscrição e registro de advogados, Caixa de Assistência dos Advogados de Roraima (CAARR), Comissões temáticas (Direitos Humanos, Mulher Advogada, entre outras), Ouvidoria e Corregedoria, cursos e eventos de capacitação jurídica, encaminhamento a serviços de assistência jurídica gratuita.",
    desc: "⚖️ <strong>Base legal:</strong> art. 5º, XIII, da Constituição Federal (livre exercício profissional) e Lei nº 8.906/1994 (Estatuto da Advocacia e da OAB). Entidade de classe responsável pela representação, seleção e disciplina dos advogados em todo o território nacional, organizada por Seccionais estaduais - a OAB-RR é a Seccional de Roraima.<br><u>Quem pode procurar:</u> advogados para questões de inscrição, regularidade profissional e atuação nas Comissões; e o cidadão em geral para denúncias contra advogados, dúvidas sobre o exercício da profissão ou encaminhamento a serviços de assistência jurídica gratuita.<br><u>Documentos:</u> variam conforme o serviço - para inscrição, diploma de bacharel em Direito, aprovação no Exame de Ordem e documentação pessoal; para denúncias contra advogado, não há exigência formal, mas recomenda-se apresentar os dados do profissional e do caso.<br>📝 <u>Como funciona:</u> atendimento presencial na sede (Av. Ville Roy, 1830) ou pelos canais da Ouvidoria (telefone, e-mail e formulário on-line); a Seccional também mantém a Caixa de Assistência dos Advogados de Roraima (CAARR) e Comissões temáticas voltadas à classe e à comunidade.<br><u>Áreas de atuação:</u> fiscalização do exercício profissional da advocacia, defesa das prerrogativas dos advogados, ouvidoria e corregedoria, além de cursos e eventos de capacitação jurídica."
