    services: "Audiências de conciliação e mediação pré-processuais e processuais em causas cíveis (dívidas, cobranças, relações de consumo), mutirões de conciliação com concessionárias de água e energia, orientação e atendimento ao cidadão sobre métodos consensuais de solução de conflitos.",
    desc: "⚖️ <strong>Base legal:</strong> Resolução nº 125/2010 do Conselho Nacional de Justiça (Política Judiciária Nacional de tratamento adequado dos conflitos); arts. 165 a 175 do Código de Processo Civil - Lei nº 13.105/2015 (instituem os centros judiciários de solução consensual de conflitos); e Lei nº 13.140/2015 (Lei de Mediação). Unidade do Poder Judiciário vinculada ao Núcleo Permanente de Métodos Consensuais de Solução de Conflitos (Nupemec) do TJRR.<br><u>Quem pode ser atendido:</u> qualquer pessoa com conflito cível pré-processual (antes de entrar com ação) ou já com processo em trâmite que possa ser resolvido por acordo, incluindo dívidas com concessionárias de água e energia, questões de consumo e cobranças.<br><u>Documentos:</u> RG e CPF; documentos relacionados ao conflito (contratos, boletos, notificações e, quando houver, número do processo).<br>📝 <u>Como funciona:</u> sessões de conciliação e mediação são conduzidas por conciliadores e mediadores capacitados pelo TJRR, que foi pioneiro em Roraima nessa capacitação em todas as comarcas; o CEJUSC de Boa Vista também realiza mutirões temáticos periódicos (ex.: energia, água).<br><u>Áreas de atuação:</u> conciliação e mediação cível, mutirões temáticos e orientação e cidadania ao público em geral. Existem outros CEJUSCs nas comarcas do interior do Estado."
