    desc: "⚖️ <strong>Base legal:</strong> art. 227 da Constituição Federal (princípio da proteção integral e prioridade absoluta de crianças e adolescentes); Lei nº 8.069/1990 (Estatuto da Criança e do Adolescente - ECA); Lei Complementar Estadual nº 221/2014 (criação da Vara); e Lei nº 13.431/2017 (institui o sistema de garantia de direitos e regula o depoimento especial de crianças e adolescentes vítimas ou testemunhas de violência). Órgão do Poder Judiciário responsável pelos processos de competência da infância e juventude na comarca de Boa Vista.<br><u>Quem pode ser atendido:</u> crianças e adolescentes em situação de risco, famílias em processos de guarda, adoção ou destituição do poder familiar, e adolescentes autores de ato infracional, geralmente encaminhados por CRAS, CREAS, Conselho Tutelar, Ministério Público ou Defensoria Pública.<br><u>Documentos:</u> variam conforme o processo - RG e CPF dos envolvidos, certidão de nascimento da criança/adolescente, relatórios técnicos (social e psicológico) já elaborados pela rede de proteção, e boletim de ocorrência quando houver.<br>📝 <u>Como funciona:</u> os casos costumam chegar por encaminhamento da rede de proteção (CRAS/CREAS/Conselho Tutelar) ou por representação do Ministério Público; a Equipe Interprofissional da Vara realiza estudos sociais e psicológicos que subsidiam as decisões judiciais, e a Sala de Depoimento Especial é usada para a oitiva de crianças e adolescentes vítimas ou testemunhas de violência, evitando a revitimização.<br><u>Áreas de atuação:</u> guarda, adoção, acolhimento institucional e destituição do poder familiar (Núcleo Cível), apuração de atos infracionais (Núcleo Infracional) e articulação com a rede de garantia de direitos do município."
