    desc: "⚖️ <strong>Base legal:</strong> art. 5º, XXXII, da Constituição Federal (defesa do consumidor como direito fundamental); Lei nº 8.078/1990 (Código de Defesa do Consumidor); Decreto Federal nº 2.181/1997 (organiza o Sistema Nacional de Defesa do Consumidor - SNDC e disciplina as sanções administrativas); e Lei Municipal nº 1.756/2016 (competências do Procon municipal). Órgão municipal de defesa do consumidor, vinculado à Prefeitura de Boa Vista, com unidade também instalada no Fórum da Cidadania (parceria com o TJRR).<br><u>Quem pode ser atendido:</u> qualquer consumidor com um problema não resolvido diretamente com uma empresa, loja ou prestador de serviço (produto com defeito, cobrança indevida, propaganda enganosa, problemas contratuais, entre outros).<br><u>Documentos:</u> RG, CPF e comprovante de residência do consumidor; nome, endereço e CNPJ do fornecedor; nota fiscal ou comprovante da compra/contratação; e, quando houver, cópias de contratos, boletos ou trocas de mensagens relacionadas à reclamação.<br>📝 <u>Como funciona:</u> o consumidor procura o Procon (presencialmente, por telefone ou canais digitais) para registrar a reclamação; o órgão notifica o fornecedor e busca a conciliação entre as partes, podendo aplicar as sanções previstas no Código de Defesa do Consumidor em caso de descumprimento.<br><u>Áreas de atuação:</u> mediação de conflitos de consumo, fiscalização de preços e práticas comerciais, e orientação e educação para o consumo consciente."
