    hours: "N/A",
    phones: ["(95) 92121-0633"],
    services: "Atenção Hospitalar - atendimento a situações de crise, internação de curta permanência e leitos de saúde mental em hospital geral.",
    desc: "Componente de Atenção Hospitalar da RAPS (leitos de saúde mental em Hospital Geral). Serve de retaguarda para os demais serviços da rede, com internações de curta duração (regra geral: inferior a 90 dias), até a estabilidade clínica do usuário.<br>Conforme a Lei n.º 10.216/2001 (art. 6º), a internação pode ser voluntária, involuntária (a pedido de terceiro, com comunicação ao Ministério Público em até 72h) ou compulsória (determinada pela Justiça). Em caso de internação involuntária, o CFM (Resoluções n.º 2.056/2013 e 2.057/2013) exige critérios clínicos objetivos, como incapacidade grave de autocuidado ou risco à vida, à saúde ou a terceiros."
