    desc: "Serviço de Atendimento Psicológico (SAP) da Universidade Federal de Roraima, ofertado como Estágio Clínico do Curso de Psicologia (supervisão da Profª Drª Joelma Ana Gutierrez Espíndula). O Plantão Psicológico busca atender, de forma pontual, demandas emocionais emergenciais, promovendo o bem-estar e a autonomia pessoal dos indivíduos.<br>Público-alvo: estudantes, técnicos, docentes e colaboradores da UFRR e comunidade externa. Pessoas a partir de 12 anos podem ser atendidas, desde que acompanhadas por um responsável legal.<br>Como participar: atendimento por ordem de chegada, sem necessidade de agendamento prévio; a ficha é preenchida presencialmente, no local."
