    phones: ["(95) 98402-2654"],
    services: "Psicologia, psicopedagogia, fisioterapia, terapia ocupacional, nutrição, neurologia e pediatria; terapia ABA (Análise do Comportamento Aplicada); capacitação de familiares e profissionais da educação/saúde.",
    desc: "Programa de Atendimento Comunitário da Assembleia Legislativa de Roraima (ALE-RR), formalizado pela Resolução Legislativa nº 002/2023 e inaugurado em 2022, sob idealização da deputada Angela Águida Portella. Atende gratuitamente crianças e adolescentes com Transtorno do Espectro Autista (TEA), hoje com mais de 900-1000 beneficiários e mais de 70 profissionais entre as duas unidades de Boa Vista.<br>Também promove audiências públicas, capacitações para pais e profissionais da educação, e ações de conscientização (ex.: participação no CITEARR/UFRR).<br>📝 Atualização cadastral de quem já é atendido: Superintendência de Programas Especiais da ALE-RR, Avenida Mário Homem de Melo, nº 3510 - Buritis.<br>Fonte: al.rr.leg.br (Programa de Atendimento Comunitário / TEAMARR)."
