    desc: "Segunda unidade do TEAMARR (Programa de Atendimento Comunitário da ALE-RR), inaugurada em 12/03/2026 na Zona Oeste de Boa Vista, para aproximar o atendimento das famílias dessa região e reduzir o deslocamento de crianças/adolescentes com TEA. Estrutura planejada para até 400 novos atendimentos, iniciando com 25 crianças de 5 a 10 anos.<br>Está prevista também a implantação de equoterapia (bairro Operário) como novo serviço terapêutico do programa.<br>Fonte: al.rr.leg.br e folhabv.com.br (mar/2026)."
