    services: "Educação Especial, Fisioterapia, Esporte Inclusivo (TEAtivo), lista de espera para atendimento mediante cadastro com documentos da criança e do responsável.",
    desc: "Instituição filantrópica sem fins lucrativos, filiada à Federação Nacional das APAEs, voltada ao suporte de pessoas com deficiência intelectual e múltipla. Oferece educação especializada, atendimento clínico/terapêutico e atividades esportivas inclusivas.<br>📋 Ingresso: cadastro com documentos da criança e do responsável para entrar na lista de espera de atendimento.<br>⚠️ Confirme endereço e telefone atualizados diretamente com a unidade antes de encaminhar um usuário, pois há divergência entre fontes quanto ao bairro exato (Calungá x São Vicente)."
