    desc: "Atendimento para Comunidades Indígenas e Zona Rural de Boa Vista.<br>⚖️ <strong>Base legal:</strong> Tipificação Nacional de Serviços Socioassistenciais (Resolução CNAS nº 109/2009) e PNAS/2004, que preveem a oferta itinerante do SUAS para populações dispersas e de difícil acesso.<br><u>Quem pode ser atendido:</u> famílias em comunidades indígenas e na zona rural de Boa Vista, sem acesso regular a uma unidade fixa de CRAS.<br><u>Documentos:</u> RG e CPF de todos os membros da família e comprovante de residência, quando disponíveis, para inclusão/atualização no Cadastro Único (CadÚnico) diretamente no local visitado.<br>📝 <u>Como funciona:</u> equipe técnica se desloca até comunidades e áreas rurais conforme cronograma de itinerário (a confirmar com a Secretaria), levando cadastramento no CadÚnico, orientações do PAIF e encaminhamentos, sem necessidade de a família se deslocar até uma unidade fixa na cidade."
