    desc: "Estrutura conjunta da Operação Acolhida, Polícia Federal e agências da ONU (ACNUR, OIM, UNICEF, UNFPA), com apoio de organizações parceiras (ex.: PADF), voltada ao primeiro atendimento e à triagem de pessoas refugiadas e migrantes, principalmente venezuelanas, em Boa Vista. No local funciona o protocolo do Registro Nacional Migratório (CRNM) junto à Polícia Federal e, desde 2023, um posto de atendimento do <strong>Cadastro Único</strong> (Sala Simone Albuquerque), que permite incluir a família migrante nos programas sociais federais logo na chegada. Também orienta sobre interiorização (deslocamento voluntário para outras cidades do país) e encaminha para a rede de abrigos e de assistência social. Atendimento sujeito a grande demanda; senha por ordem de chegada."
