    desc: "A recuperação de senha deve ser realizada diretamente pelo sistema gov.br: 1) Acesse o Meu INSS (https://meu.inss.gov.br); 2) Clique em 'Entrar com gov.br'; 3) Digite o CPF e clique em 'Avançar'; 4) Clique em 'Esqueci minha senha'; 5) Na tela de Recuperação de Conta, marque 'Não sou um robô' e avance; 6) Escolha uma forma de recuperação: e-mail, SMS, aplicativo gov.br (reconhecimento facial) ou bancos credenciados; 7) Siga as instruções para criar uma nova senha.<br>📌 Caso não consiga recuperar online: utilizar formulário de atendimento ou comparecer a uma agência com documento com foto.<br>Fonte: gov.br/inss (Canais de Atendimento &gt; Meu INSS &gt; Esqueceu a senha?)."
