    desc: "A Tarifa Social de Água e Esgoto, prevista na Lei Federal nº 14.898/2024 e regulamentada localmente pela CAER (Companhia de Águas e Esgotos de Roraima), garante desconto de 50% sobre a tarifa de água e esgoto até um determinado volume mensal de consumo para famílias de baixa renda.<br>Requisitos: • Família inscrita no CadÚnico com renda mensal por pessoa de até meio salário mínimo, ou com integrante beneficiário do BPC/LOAS; • Cadastro atualizado no CadÚnico; • Unidade consumidora sem débitos pendentes com a CAER; • Em caso de imóvel alugado, apresentar contrato de locação vigente.<br>⚠️ Observações técnicas: a concessão pode ser cancelada caso vistoria constate divergência entre os dados declarados e a situação real do imóvel, retornando o usuário à tarifa residencial normal; a CAER também realiza ações itinerantes em bairros para cadastramento de famílias e renegociação de débitos.<br>Canais para solicitação: • E-mail: atendimento@caer.com.br; • Central telefônica: 0800-280-9520; • Presencialmente em uma Loja de Atendimento da CAER, com CadÚnico atualizado e documentos pessoais."
