    services: "Kit de antena parabólica digital (antena, receptor e cabos) com instalação 100% gratuita.",
    desc: "O programa Siga Antenado foi sucedido pelo Brasil Antenado, executado pela EAF (Entidade Administradora da Faixa) em parceria com o Ministério das Comunicações (MCom) e a Anatel. Entrega gratuitamente o kit da nova parabólica digital (antena, receptor digital e cabos), com instalação domiciliar sem qualquer custo, dando acesso a mais de 100 canais de TV aberta.<br><br><strong>Requisitos:</strong> • Estar inscrito(a) no Cadastro Único (CadÚnico); • Morar em um dos municípios contemplados na fase atual do programa.<br>⚠️ Não é necessário já ter uma antena parabólica antiga em casa, nem ser beneficiário do Bolsa Família - basta o CadÚnico e residir em cidade participante.<br><br><strong>Em Roraima:</strong> na Fase B (13/10/2025 a 13/03/2026), o programa contempla os municípios de Alto Alegre, Amajarí e Uiramutã (cerca de 9 mil famílias aptas). Boa Vista não constava entre os municípios contemplados até o momento - oriente o usuário a confirmar a situação atualizada do seu município no site oficial ou pelo WhatsApp, já que a cobertura é ampliada em novas fases.<br><br><strong>Como solicitar:</strong> 1) Confirmar se o município é contemplado, pelo site ou telefone; 2) Agendar pelo WhatsApp oficial (0800 729 2404) ou pela Central Telefônica; 3) Aguardar a visita técnica agendada - todo o processo (agendamento, visita e entrega/instalação do kit) é 100% gratuito, sem cobrança em dinheiro, Pix ou cartão em nenhuma etapa.<br>Site: https://www.brasilantenado.org.br/<br>Dúvidas frequentes: https://www.brasilantenado.org.br/duvidas/<br>E-mail: atendimento@brasilantenado.org.br"
