    desc: "Desde 2024 a emissão é totalmente digital, sem necessidade de envio de documentos pelos Correios. Requisitos (basta atender a um): • Estar inscrito no Cadastro-Inclusão (Registro de Referência da Pessoa com Deficiência) e no CadÚnico; • Ou ter um médico com registro ativo no CRM atestando a condição de pessoa com deficiência diretamente no sistema. Etapas: • Acessar o sistema com conta Gov.br (nível Bronze, Prata ou Ouro); • Preencher a solicitação e aguardar a validação; • A credencial digital é emitida automaticamente e pode ser impressa ou apresentada pelo celular.<br>⚠️ Observações técnicas: a credencial não tem mais prazo de validade fixo; a ANTT prorrogou até 31/12/2026 a validade das credenciais que venceriam em 31/12/2025.<br>Link para solicitação: https://passelivre.antt.gov.br/<br><br>⚠️ Não confundir com o Passe Livre Intermunicipal (estadual), concedido pela SETRABES para pessoas com deficiência no transporte intermunicipal dentro de Roraima, com atendimento presencial no CEAC \"Valdenhilton Gomes\" (Av. Mário Homem de Melo, 4534 - Caimbé, Boa Vista-RR)."
