    desc: "Programa do Governo Federal (Ministério da Saúde, Decreto nº 11.432/2023) que garante o acesso gratuito a absorventes higiênicos para pessoas de 10 a 49 anos em situação de vulnerabilidade e baixa renda. Em Roraima, no primeiro ano de execução o programa já beneficiou cerca de 3,6 mil pessoas, com a distribuição de 294 mil absorventes. Requisitos: • Estar inscrito(a) e com o Cadastro Único (CadÚnico) atualizado - quem já possui o CadÚnico em dia não precisa comparecer ao CRAS. Etapas em Boa Vista: 1) Atualizar ou realizar o CadÚnico em um CRAS da capital; 2) Emitir a autorização pelo site ou aplicativo 'Meu SUS Digital', no campo 'Programa Dignidade Menstrual' > 'Emitir Autorização' (válida por 180 dias); 3) Comparecer a uma farmácia credenciada ao Programa Farmácia Popular do Brasil (PFPB) em Boa Vista, com documento oficial com foto e CPF, para retirar 40 unidades de absorventes (equivalentes a dois ciclos menstruais, a cada 56 dias).<br>⚠️ A rede de farmácias credenciadas em Boa Vista pode ser consultada no site do Farmácia Popular ou diretamente no app Meu SUS Digital."
